BehaviorDocument Doc(string source)=>new(source,adapter,sourceFile:sourceFile);
BehaviorNode Phase(BehaviorDocument document,string name)=>document.AllNodes.Single(n=>n.Kind=="State"&&document.StateName(n.Id)==name);
StudioProject Project(BehaviorDocument document)=>new(){SourceFile=sourceFile,Source=document.Source,Identities=document.Identities,EntityId=entity,Seed=7,Player=new(Invulnerable:true)};
foreach(var kind in new[]{"FollowDistance","LockedFollowDistance"})
{
    var doc=Doc(Source(kind));var moving=Phase(doc,"moving");var before=doc.Source;var ids=doc.Identities;var candidate=adapter.CompletionMovements(doc,moving).Single();
    Check(candidate.Kind==kind&&candidate.Expression=="move"&&candidate.TransitionKind==kind+"CompleteTransition",kind+" discovers the exact native local movement reference without executing the factory");
    var created=adapter.AddCompletionRoute(doc,moving.Id,candidate.ReferenceId,doc.Revision,"done",d=>adapter.Validate(d,entity));
    Check(adapter.ReadCompletionBinding(doc,doc.Find(created))?.MovementReferenceId==candidate.ReferenceId&&ids.All(i=>doc.Identities.Any(n=>n.Id==i.Id)),kind+" route creation refers to the existing instance and preserves every source identity");
    Check(doc.Undo()&&doc.Source==before&&doc.Redo()&&doc.Find(created).Kind==kind+"CompleteTransition",kind+" complete source history retains the created transition identity");
    await using(var native=await CompiledRuntime.StartAsync(adapter.ServerRoot,Project(doc))){await native.AdvanceAsync(new(),800);Check(native.Entities.Single() is{Phase:"done",X:66.5f},kind+" native completion route switches after its actual two-tile segment");}
    doc.LockedNodes.Add(created);Reject(()=>adapter.RelinkCompletionRoute(doc,created,candidate.ReferenceId,doc.Revision,d=>adapter.Validate(d,entity)),kind+" transition locks protect the instance relationship");doc.LockedNodes.Clear();
    Reject(()=>adapter.AddCompletionRoute(doc,moving.Id,candidate.ReferenceId,doc.Revision-1,"done",d=>adapter.Validate(d,entity)),kind+" stale completion proposals reject before changing source");
}
