var available=adapter.CompletionMovements(wrongDoc,wrongTransition).Single();var previous=wrongDoc.Source;var retained=wrongDoc.Identities;var replaced=wrongTransition.Children.SelectMany(n=>n.Descendants()).Select(n=>n.Id).ToHashSet();adapter.RelinkCompletionRoute(wrongDoc,wrongTransition.Id,available.ReferenceId,wrongDoc.Revision,d=>adapter.Validate(d,entity));
