await using(var native=await CompiledRuntime.StartAsync(adapter.ServerRoot,Project(wrongDoc))){await native.AdvanceAsync(new(),800);Check(native.Entities.Single().Phase=="done","Relinking the real instance repairs native completion behavior");}
