{var source=Source("FollowDistance",extra).Replace(" } } }"," } static void Reset(ref FollowDistance value){} } }");var doc=Doc(source);Check(adapter.CompletionMovements(doc,Phase(doc,"moving")).Count==0,"Reassigned or writable captured movement needs source ownership: "+extra);}
